package swedueltest

import (
	"reflect"
	"sort"
	"testing"

	"github.com/go-chi/chi/v5"
)


func newCtx(pairs ...string) *chi.Context {
	rctx := chi.NewRouteContext()
	for i := 0; i+1 < len(pairs); i += 2 {
		rctx.URLParams.Add(pairs[i], pairs[i+1])
	}
	return rctx
}

func TestURLParamMap(t *testing.T) {
	ctx := newCtx("id", "1", "name", "alice")
	m := ctx.URLParamMap()
	if len(m) != 2 {
		t.Fatalf("expected 2 entries, got %d", len(m))
	}
	if m["id"] != "1" {
		t.Errorf("expected id=1, got %q", m["id"])
	}
	if m["name"] != "alice" {
		t.Errorf("expected name=alice, got %q", m["name"])
	}

	// Duplicate keys: most recent wins, consistent with URLParam.
	dup := newCtx("id", "1", "id", "2")
	dm := dup.URLParamMap()
	if len(dm) != 1 {
		t.Fatalf("expected 1 entry for dup keys, got %d", len(dm))
	}
	if dm["id"] != dup.URLParam("id") {
		t.Errorf("URLParamMap value %q != URLParam value %q", dm["id"], dup.URLParam("id"))
	}

	// nil receiver safety.
	var nilCtx *chi.Context
	if got := nilCtx.URLParamMap(); got == nil || len(got) != 0 {
		t.Errorf("expected empty map for nil ctx, got %v", got)
	}
}

func TestURLParamNames(t *testing.T) {
	ctx := newCtx("a", "1", "b", "2", "a", "3")
	names := ctx.URLParamNames()
	sort.Strings(names)
	if !reflect.DeepEqual(names, []string{"a", "b"}) {
		t.Errorf("expected [a b], got %v", names)
	}

	empty := newCtx()
	if len(empty.URLParamNames()) != 0 {
		t.Errorf("expected no names, got %v", empty.URLParamNames())
	}
}

func TestHasURLParam(t *testing.T) {
	ctx := newCtx("foo", "bar")
	if !ctx.HasURLParam("foo") {
		t.Error("expected HasURLParam(foo) to be true")
	}
	if ctx.HasURLParam("missing") {
		t.Error("expected HasURLParam(missing) to be false")
	}
	var nilCtx *chi.Context
	if nilCtx.HasURLParam("foo") {
		t.Error("expected nil ctx HasURLParam to be false")
	}
}

