package swedueltest

import (
	"reflect"
	"testing"

	"github.com/go-chi/chi/v5"
)

func bugCtx(pairs ...string) *chi.Context {
	rctx := chi.NewRouteContext()
	for i := 0; i+1 < len(pairs); i += 2 {
		rctx.URLParams.Add(pairs[i], pairs[i+1])
	}
	return rctx
}

// A single captured parameter must be reported by URLParamNames.
func TestURLParamNamesSingle(t *testing.T) {
	ctx := bugCtx("only", "v")
	names := ctx.URLParamNames()
	if !reflect.DeepEqual(names, []string{"only"}) {
		t.Errorf("expected [only], got %v", names)
	}
}

// The first (oldest) captured parameter must be enumerated.
func TestURLParamNamesIncludesFirst(t *testing.T) {
	ctx := bugCtx("id", "1", "name", "alice", "slug", "x")
	names := ctx.URLParamNames()
	found := false
	for _, n := range names {
		if n == "id" {
			found = true
		}
	}
	if !found {
		t.Errorf("expected URLParamNames to include first param 'id', got %v", names)
	}
	if len(names) != 3 {
		t.Errorf("expected 3 names, got %d (%v)", len(names), names)
	}
}

